
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_cs1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_cs1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.453561794197289e-02, -5.443159376965511e-02, -5.427581545226601e-02, -5.403812275064716e-02, -5.366510651134945e-02, -5.305422787994075e-02, -5.198672241392187e-02, -4.993439611650079e-02, -4.550183934733613e-02, -3.575668533123747e-02, -2.522161096221788e-02, -3.046899524909810e-02, -3.041208415347284e-02, -2.756683338728187e-02, -1.877273390402485e-02, -2.714029699397470e-03, 1.251371246108629e-02, 9.337852114135787e-03, 2.409134008676153e-03, 2.811024433403796e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


